    # memoization
    memo = {}

    def get_moves(player_mask, overall_mask, n):
        moves = []
        for i in range(n):
            if not (overall_mask & (1 << i)):
                # Check if i is consecutive to any in player_mask
                is_consecutive = False
                for j in range(n):
                    if (player_mask & (1 << j)):
                        if abs(i - j) == 1:
                            is_consecutive = True
                            break
                if not is_consecutive:
                    moves.append(i)
        return moves

    def minimax(alice_mask, bob_mask, turn):
        state = (alice_mask, bob_mask, turn)
        if state in memo:
            return memo[state]

        overall_mask = alice_mask | bob_mask
        if overall_mask == (1 << n) - 1:
            return 0 # Draw

        if turn == 0: # Alice's turn
            moves = get_moves(alice_mask, overall_mask, n)
            if not moves:
                return -1 # Alice loses

            results = []
            for m in moves:
                results.append(minimax(alice_mask | (1 << m), bob_mask, 1))

            if -1 in results: # Can Alice move to a state where Bob loses?
                res = 1
            elif 0 in results: # Can Alice move to a draw?
                res = 0
            else:
                res = -1
            memo[state] = res
            return res
        else: # Bob's turn
            moves = get_moves(bob_mask, overall_mask, n)
            if not moves:
                return 1 # Bob loses (so Alice wins)

            results = []
            for m in moves:
                results.append(minimax(alice_mask, bob_mask | (1 << m), 0))

            if 1 in results: # Can Bob move to a state where Alice loses?
                res = -1
            elif 0 in results: # Can Bob move to a draw?
                res = 0
            else:
                res = 1
            memo[state] = res
            return res

    # Result: 1 means Alice wins, -1 means Bob wins, 0 means Draw
    return minimax(0, 0, 0)

