import collections

def solve_game(n):
    # Memoization table: maps (frozenset(A), frozenset(B), turn) -> score (0.0, 0.5, 1.0)
    memo = {}

    def is_valid_move(x, current_A, current_B, is_alice_turn):
        # Rule (i): Must not have been chosen
        if x in current_A or x in current_B:
            return False

        # Rule (ii): Cannot be consecutive to own previous choices
        if is_alice_turn:
            # Check adjacency to A
            for a in current_A:
                if abs(x - a) == 1:
                    return False
        else:
            # Check adjacency to B
            for b in current_B:
                if abs(x - b) == 1:
                    return False

        return True

    def get_possible_moves(current_A, current_B, is_alice_turn):
        moves = []
        for x in range(1, n + 1):
            if is_valid_move(x, current_A, current_B, is_alice_turn):
                moves.append(x)
        return moves

    def minimax(current_A, current_B, is_alice_turn):
        state = (frozenset(current_A), frozenset(current_B), is_alice_turn)
        if state in memo:
            return memo[state]

        C = current_A.union(current_B)

        # Terminal Condition 1: Draw (All numbers chosen)
        if len(C) == n:
            return 0.5

        possible_moves = get_possible_moves(current_A, current_B, is_alice_turn)

        # Terminal Condition 2: Loss
        if not possible_moves:
            if is_alice_turn:
                # Alice cannot move -> Bob wins
                return 0.0
            else:
                # Bob cannot move -> Alice wins
                return 1.0

        # Recursive step
        if is_alice_turn:
            # Alice maximizes her score
            max_score = -1.0
            for move in possible_moves:
                score = minimax(current_A.union({move}), current_B, False) # Next turn is Bob's
                max_score = max(max_score, score)
            result = max_score
        else:
            # Bob minimizes Alice's score (i.e., maximizes his own chance of winning)
            min_score = 2.0
            for move in possible_moves:
                score = minimax(current_A, current_B.union({move}), True) # Next turn is Alice's
                min_score = min(min_score, score)
            result = min_score

        memo[state] = result
        return result

    # Alice starts (is_alice_turn = True)
    return minimax(set(), set(), True)

